import{_ as a,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Permitir credenciais salvas na tela de login","description":"","frontmatter":{"title":"Permitir credenciais salvas na tela de login","id":"eproc-login-gerenciador-senhas","plataforma":"eproc","grupo":"Geral do eproc","plano":"free","desde":"1.0.7","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-login-gerenciador-senhas"}]]},"headers":[],"relativePath":"funcionalidades/eproc-login-gerenciador-senhas.md","filePath":"funcionalidades/eproc-login-gerenciador-senhas.md"}'),n={name:"funcionalidades/eproc-login-gerenciador-senhas.md"};function i(l,e,d,c,t,p){return o(),r("div",null,e[0]||(e[0]=[s('<h1 id="permitir-credenciais-salvas-na-tela-de-login" tabindex="-1">Permitir credenciais salvas na tela de login <a class="header-anchor" href="#permitir-credenciais-salvas-na-tela-de-login" aria-label="Permalink to &quot;Permitir credenciais salvas na tela de login&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>O campo de senha da tela de login do eproc é feito de um jeito que impede o navegador de reconhecê-lo, então o gerenciador de senhas não oferece salvar nem preencher. Este recurso corrige o campo para que o navegador possa salvar e preencher usuário e senha.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, tela de login.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Entre no eproc digitando usuário e senha.</li><li>O navegador oferece salvar a senha. Aceite, se quiser.</li><li>Nas próximas vezes, o navegador preenche os campos.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A senha é guardada pelo gerenciador de senhas do navegador (Chrome ou Edge), não pelo eploc. O eploc não lê nem armazena senhas.</li><li>Só atua no formulário de login. Campos de senha de confirmação (como na assinatura de documentos) não são alterados.</li></ul>',11)]))}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
